pt-04-upload-validation.command:
uv run --quiet python -c "import sys; sys.path.insert(0,'src'); from uploads import validate_upload, UploadRejected;
for name in ('../etc/passwd.pdf', '.hidden.pdf', 'a/b.pdf', 'a\\\\b.pdf', 'report.exe', 'report'):
    try:
        validate_upload(name, 10)
    except UploadRejected:
        continue
    raise SystemExit('accepted ' + name)"

uv run --quiet python -c "import sys; sys.path.insert(0,'src'); from uploads import validate_upload, UploadRejected;
seen = set()
for name, size in (('big.pdf', 50*1024*1024), ('note.exe', 10), ('a/b.pdf', 10), ('.hidden.pdf', 10)):
    try:
        validate_upload(name, size)
    except UploadRejected as exc:
        seen.add(str(exc))
assert len(seen) == 4, seen"
